from django.contrib.sessions.models import Session
from django.contrib.sessions.backends.db import SessionStore
from django.contrib.messages.storage.session import SessionStorage
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from django.contrib.auth import get_user_model

User = get_user_model()

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def send_user_flash_banner(request):
    # Only superusers or organization administrators can broadcast session messages
    if not (request.user.is_staff and request.user.has_perm('auth.change_user')):
        return Response({'error': 'Insufficient permissions to broadcast banners'}, status=status.HTTP_403_FORBIDDEN)

    target_user_id = request.data.get('user_id')
    banner_message = request.data.get('message')

    try:
        target_user = User.objects.get(pk=target_user_id, organization=request.user.organization)
    except User.DoesNotExist:
        return Response({'error': 'Target user not found in organization'}, status=status.HTTP_404_NOT_FOUND)

    for session_obj in Session.objects.filter(expire_date__gte=request.session.get_expiry_date()):
        data = session_obj.get_decoded()
        if data.get('_auth_user_id') == str(target_user.id):
            s = SessionStore(session_key=session_obj.session_key)
            existing = s.get(SessionStorage.session_key, [])
            existing.append(f"warning:{banner_message}")
            s[SessionStorage.session_key] = existing
            s.save()

    return Response({'status': 'banner dispatched'})
